#### 三路快速排序
维护四段：小于 pivot、等于 pivot、尚未检查、大于 pivot。交换到右侧未知元素后不能直接增加 current；交换进来的值还未分类。只递归较短分区，长分区循环处理，使最坏递归栈保持 O(log n)，但时间仍可能 O(n²)。
<!-- interview:QuickSort -->
```cpp
void quickRange(std::vector<int> &values, std::size_t first, std::size_t last) {
    while (last - first > 1) {
        int pivot = values[first + (last - first) / 2];
        auto less = first, current = first, greater = last;
        while (current < greater) {
            if (values[current] < pivot)
                std::swap(values[less++], values[current++]);
            else if (values[current] > pivot)
                std::swap(values[current], values[--greater]);
            else
                ++current;
        }
        // 只递归较短分区，较长分区迭代处理，递归栈 O(log n)。
        if (less - first < last - greater) {
            quickRange(values, first, less);
            first = greater;
        } else {
            quickRange(values, greater, last);
            last = less;
        }
    }
}
void quickSort(std::vector<int> &values) {
    quickRange(values, 0, values.size());
}
```
参考：[Princeton Algorithms 的三路划分源码](https://github.com/kevin-wayne/algs4/blob/master/src/main/java/edu/princeton/cs/algs4/Quick3way.java)

